// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x020205);
scene.fog = new THREE.FogExp2(0x020205, 0.015);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 15, 35);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.4;
controls.maxDistance = 80;
controls.minDistance = 5;

// Lights
const ambientLight = new THREE.AmbientLight(0x222222, 2);
scene.add(ambientLight);

const pLight1 = new THREE.PointLight(0xff0080, 3, 100);
pLight1.position.set(15, 10, 10);
scene.add(pLight1);

const pLight2 = new THREE.PointLight(0x00ffcc, 3, 100);
pLight2.position.set(-15, -10, -10);
scene.add(pLight2);

// Central wireframe core
const coreGeo = new THREE.IcosahedronGeometry(3, 2);
const coreMat = new THREE.MeshBasicMaterial({
  color: 0xffffff,
  wireframe: true,
  transparent: true,
  opacity: 0.15
});
const core = new THREE.Mesh(coreGeo, coreMat);
scene.add(core);

const innerGeo = new THREE.IcosahedronGeometry(2.5, 1);
const innerMat = new THREE.MeshBasicMaterial({
  color: 0x00ffff,
  wireframe: true,
  transparent: true,
  opacity: 0.08
});
const innerCore = new THREE.Mesh(innerGeo, innerMat);
scene.add(innerCore);

// Particle Wave Field
const cols = 120;
const rows = 120;
const count = cols * rows;
const spacing = 0.5;
const geometry = new THREE.BufferGeometry();
const positions = new Float32Array(count * 3);
const colors = new Float32Array(count * 3);

const c1 = new THREE.Color(0x4400ff);
const c2 = new THREE.Color(0xff0080);
const c3 = new THREE.Color(0x00ffff);
const tempColor = new THREE.Color();

let idx = 0;
const offsetX = (cols * spacing) / 2;
const offsetZ = (rows * spacing) / 2;

for (let i = 0; i < cols; i++) {
  for (let j = 0; j < rows; j++) {
    positions[idx * 3] = i * spacing - offsetX;
    positions[idx * 3 + 1] = 0;
    positions[idx * 3 + 2] = j * spacing - offsetZ;
    idx++;
  }
}

geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

const material = new THREE.PointsMaterial({
  size: 0.25,
  vertexColors: true,
  blending: THREE.AdditiveBlending,
  depthWrite: false,
  transparent: true,
  opacity: 0.9
});

const particles = new THREE.Points(geometry, material);
scene.add(particles);

// Background stars
const starCount = 2000;
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(starCount * 3);
for (let i = 0; i < starCount * 3; i++) {
  starPos[i] = (Math.random() - 0.5) * 200;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.15,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending
});
const stars = new THREE.Points(starGeo, starMat);
scene.add(stars);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const time = clock.getElapsedTime();
  const posArray = particles.geometry.attributes.position.array;
  const colArray = particles.geometry.attributes.color.array;

  for (let i = 0; i < count; i++) {
    const x = posArray[i * 3];
    const z = posArray[i * 3 + 2];

    // Complex wave terrain
    const y = Math.sin(x * 0.15 + time * 1.2) * 2.5 +
              Math.cos(z * 0.12 + time * 0.9) * 2.5 +
              Math.sin((x + z) * 0.08 + time * 1.8) * 1.8 +
              Math.sin(Math.sqrt(x*x + z*z) * 0.2 - time * 2) * 1.2;

    posArray[i * 3 + 1] = y;

    // Color mapping based on height and position
    const t = (y + 6) / 12;
    const wave = Math.sin(time * 0.5 + x * 0.05 + z * 0.05) * 0.5 + 0.5;

    tempColor.lerpColors(c1, c2, Math.max(0, Math.min(1, t)));
    tempColor.lerp(c3, wave * 0.7);

    colArray[i * 3] = tempColor.r;
    colArray[i * 3 + 1] = tempColor.g;
    colArray[i * 3 + 2] = tempColor.b;
  }

  particles.geometry.attributes.position.needsUpdate = true;
  particles.geometry.attributes.color.needsUpdate = true;

  // Animate core
  core.rotation.x = time * 0.4;
  core.rotation.y = time * 0.6;
  core.scale.setScalar(1 + Math.sin(time * 1.5) * 0.15);

  innerCore.rotation.x = -time * 0.3;
  innerCore.rotation.y = -time * 0.5;
  innerCore.scale.setScalar(1 + Math.cos(time * 2) * 0.1);

  // Pulse lights
  pLight1.intensity = 2 + Math.sin(time * 3) * 1;
  pLight2.intensity = 2 + Math.cos(time * 2.5) * 1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handler
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

